using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.InputSystem;using Demo6.Game;
public static class StyleV4FinalAudit{public static object Run(){var shader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/Shaders/SpriteFlash.shader");var art=AssetDatabase.LoadAssetAtPath<CombatArtSet>("Assets/Data/Combat/CombatArtSet.asset");var type=typeof(Editor).Assembly.GetType("UnityEditor.GameView");var view=Resources.FindObjectsOfTypeAll(type).Cast<EditorWindow>().First();var index=type.GetProperty("selectedSizeIndex",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(view);var result=new{playing=EditorApplication.isPlaying,compiling=EditorApplication.isCompiling,paused=EditorApplication.isPaused,background=Application.runInBackground,viewIndex=index,scenes=UnityEditor.SceneManagement.EditorSceneManager.GetSceneManagerSetup().Select(s=>new{s.path,s.isLoaded,s.isActive}).ToArray(),activeSceneDirty=UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty,artDirty=EditorUtility.IsDirty(art),shaderHasError=ShaderUtil.ShaderHasError(shader),shaderMessages=ShaderUtil.GetShaderMessages(shader).Select(m=>new{severity=m.severity.ToString(),m.message,m.line}).ToArray(),temporaryInputDevices=InputSystem.devices.Where(d=>d.name.StartsWith("V4")).Select(d=>d.name).ToArray(),parts=Directory.GetFiles("Assets/Art/TopDown/PlayerV4","*.png").Select(path=>{var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);return new{path,width=s.texture.width,height=s.texture.height,ppu=s.pixelsPerUnit,pivot=s.pivot.ToString(),loaded=s!=null};}).ToArray()};File.WriteAllText("검증/비주얼-개선-v4/final-editor-audit.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}}
